package com.cosmeticcannon;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Projectile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Cosmetic Cannon",
	description = "Replaces cannonball projectiles with custom visuals, configurable per firing direction",
	tags = {"cannon", "cosmetic", "projectile", "cannonball", "visual", "swap"}
)
public class CosmeticCannonPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CosmeticCannonPlugin.class);

	// Projectile IDs for cannonball types fired by the dwarf multicannon.
	private static final int CANNONBALL         = 53;   // standard cannonball
	private static final int GRANITE_CANNONBALL = 1443; // granite cannonball
	private static final int RESKIN_CANNONBALL  = 2018; // cannon reskin variant (confirmed in-game)

	// Shared rainbow counter - advances once per swapped shot across all directions.
	private int rainbowIndex = 0;

	@Inject
	private Client client;

	@Inject
	private CosmeticCannonConfig config;

	@Subscribe
	public void onProjectileMoved(ProjectileMoved event)
	{
		if (!config.swapEnabled())
		{
			return;
		}

		Projectile projectile = event.getProjectile();
		int id = projectile.getId();

		if (id != CANNONBALL && id != GRANITE_CANNONBALL && id != RESKIN_CANNONBALL)
		{
			return;
		}

		// onProjectileMoved fires every tick for each active projectile, not just
		// on spawn. Guard against processing a projectile we already suppressed.
		if (projectile.getRemainingCycles() <= 0)
		{
			return;
		}

		WorldPoint src = projectile.getSourcePoint();
		WorldPoint tgt = projectile.getTargetPoint();

		if (src == null || tgt == null)
		{
			return;
		}

		int dx = tgt.getX() - src.getX();
		int dy = tgt.getY() - src.getY();

		if (dx == 0 && dy == 0)
		{
			log.debug("Cannonball projectile {} has identical source and target; skipping swap", id);
			return;
		}

		int replacementId = resolveReplacement(dx, dy);
		if (replacementId <= 0)
		{
			return;
		}

		// Chinbompa technique: spawn a replacement projectile copying all timing
		// and trajectory parameters, then suppress the original by zeroing its end cycle.
		client.createProjectile(
			replacementId,
			src, projectile.getStartHeight(), projectile.getSourceActor(),
			tgt, projectile.getEndHeight(),   projectile.getTargetActor(),
			client.getGameCycle(), projectile.getEndCycle(),
			projectile.getSlope(), 0
		);
		projectile.setEndCycle(0);

		log.debug("Swapped cannonball {} -> {} (mode={}, dx={}, dy={})",
			id, replacementId, config.swapMode(), dx, dy);
	}

	/**
	 * Resolves the replacement projectile ID based on the current swap mode.
	 * Returns <= 0 if no swap should occur.
	 */
	private int resolveReplacement(int dx, int dy)
	{
		switch (config.swapMode())
		{
			case RANDOM:
				return ProjectileSwap.random().getProjectileId();

			case RAINBOW:
			{
				int rainbowId = ProjectileSwap.RAINBOW_SEQUENCE[rainbowIndex % ProjectileSwap.RAINBOW_SEQUENCE.length];
				rainbowIndex++;
				return rainbowId;
			}

			case CUSTOM:
			{
				int dirIndex = directionIndex(dx, dy);
				return swapForDirection(dirIndex).getProjectileId();
			}

			default:
				return -1;
		}
	}

	/**
	 * Maps a source->target delta to one of 8 compass direction indices.
	 * 0=E, 1=NE, 2=N, 3=NW, 4=W, 5=SW, 6=S, 7=SE
	 * OSRS world coords: +X = east, +Y = north.
	 */
	private int directionIndex(int dx, int dy)
	{
		return (int) Math.round(Math.atan2(dy, dx) / (Math.PI / 4)) & 7;
	}

	/**
	 * Returns the configured ProjectileSwap preset for the given direction index.
	 * Used in Custom mode.
	 */
	private ProjectileSwap swapForDirection(int dirIndex)
	{
		switch (dirIndex)
		{
			case 0: return config.projectileEast();
			case 1: return config.projectileNorthEast();
			case 2: return config.projectileNorth();
			case 3: return config.projectileNorthWest();
			case 4: return config.projectileWest();
			case 5: return config.projectileSouthWest();
			case 6: return config.projectileSouth();
			case 7: return config.projectileSouthEast();
			default: return ProjectileSwap.NONE;
		}
	}

	@Provides
	CosmeticCannonConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CosmeticCannonConfig.class);
	}
}

package com.cosmeticcannon;

/**
 * Top-level swap mode. Controls how the replacement projectile is chosen.
 */
public enum SwapMode
{
	RANDOM  ("Random"),
	RAINBOW ("Rainbow Cycle"),
	CUSTOM  ("Custom (per direction)");

	private final String displayName;

	SwapMode(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.cosmeticcannon;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("cosmeticcannon")
public interface CosmeticCannonConfig extends Config
{
	@ConfigSection(
		name = "General",
		description = "Global settings",
		position = 0
	)
	String generalSection = "general";

	@ConfigItem(
		keyName = "swapEnabled",
		name = "Enable swap",
		description = "Master toggle. When off, all cannonball projectiles are unchanged.",
		section = generalSection,
		position = 0
	)
	default boolean swapEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "swapMode",
		name = "Mode",
		description = "<html>Random: each shot picks a random projectile from the preset list.<br>" +
			"Rainbow: cycles through a spectrum of colours shot by shot.<br>" +
			"Custom: choose a replacement per firing direction from the preset list.</html>",
		section = generalSection,
		position = 1
	)
	default SwapMode swapMode()
	{
		return SwapMode.CUSTOM;
	}

	// -------------------------------------------------------------------------
	// Custom direction overrides — preset dropdown per direction.
	// Active when Mode is set to Custom.
	// -------------------------------------------------------------------------

	@ConfigSection(
		name = "Custom Direction Overrides",
		description = "Only used when Mode is set to Custom. " +
			"Choose a replacement projectile for each of the 8 firing directions. " +
			"None leaves that direction unchanged.",
		position = 2
	)
	String directionSection = "directions";

	@ConfigItem(
		keyName = "projectileNorth",
		name = "North",
		description = "Replacement projectile when the cannon fires North.",
		section = directionSection,
		position = 0
	)
	default ProjectileSwap projectileNorth()
	{
		return ProjectileSwap.NONE;
	}

	@ConfigItem(
		keyName = "projectileNorthEast",
		name = "North-East",
		description = "Replacement projectile when the cannon fires North-East.",
		section = directionSection,
		position = 1
	)
	default ProjectileSwap projectileNorthEast()
	{
		return ProjectileSwap.NONE;
	}

	@ConfigItem(
		keyName = "projectileEast",
		name = "East",
		description = "Replacement projectile when the cannon fires East.",
		section = directionSection,
		position = 2
	)
	default ProjectileSwap projectileEast()
	{
		return ProjectileSwap.NONE;
	}

	@ConfigItem(
		keyName = "projectileSouthEast",
		name = "South-East",
		description = "Replacement projectile when the cannon fires South-East.",
		section = directionSection,
		position = 3
	)
	default ProjectileSwap projectileSouthEast()
	{
		return ProjectileSwap.NONE;
	}

	@ConfigItem(
		keyName = "projectileSouth",
		name = "South",
		description = "Replacement projectile when the cannon fires South.",
		section = directionSection,
		position = 4
	)
	default ProjectileSwap projectileSouth()
	{
		return ProjectileSwap.NONE;
	}

	@ConfigItem(
		keyName = "projectileSouthWest",
		name = "South-West",
		description = "Replacement projectile when the cannon fires South-West.",
		section = directionSection,
		position = 5
	)
	default ProjectileSwap projectileSouthWest()
	{
		return ProjectileSwap.NONE;
	}

	@ConfigItem(
		keyName = "projectileWest",
		name = "West",
		description = "Replacement projectile when the cannon fires West.",
		section = directionSection,
		position = 6
	)
	default ProjectileSwap projectileWest()
	{
		return ProjectileSwap.NONE;
	}

	@ConfigItem(
		keyName = "projectileNorthWest",
		name = "North-West",
		description = "Replacement projectile when the cannon fires North-West.",
		section = directionSection,
		position = 7
	)
	default ProjectileSwap projectileNorthWest()
	{
		return ProjectileSwap.NONE;
	}
}

package com.cosmeticcannon;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;

/**
 * Replacement projectile presets for Custom mode per-direction selection.
 *
 * Boss projectile IDs sourced from the Projectile Override plugin by Loze-Put:
 *   https://github.com/Loze-Put/projectile-override
 *
 * Additional IDs researched via the RuneMonk entity viewer:
 *   https://runemonk.com/tools/entityviewer-beta
 *
 * Swap technique adapted from the Chinbompa plugin by sigterm:
 *   https://github.com/runelite/plugin-hub (search: chinbompa)
 */
public enum ProjectileSwap
{
	// -------------------------------------------------------------------------
	// No swap for this direction
	// -------------------------------------------------------------------------
	NONE ("None", -1),

	// -------------------------------------------------------------------------
	// Boss projectiles - sourced from Loze-Put/projectile-override
	// -------------------------------------------------------------------------
	AKKHA_MAGIC               ("Red - 2253",          2253),
	AKKHA_RANGED              ("Gold - 2255",         2255),

